namespace ElymsPet { public static class RepositoryLearningExample { public static DomainGraph Create(){var graph=new DomainGraph{Id="repo-learning-vllm-"+Guid.NewGuid().ToString("N"),Title="vLLM → Ascend · 源码导览",Description="四步学习路线；不同仓库独立快照，不声明兼容版本配对。研究采集：2026-11-12。"};
graph.Nodes.Add(new DomainNode{Id="scheduler",Title="调度一次请求",Tier="CORE",Summary="观察 token 预算如何分配；沿本函数查找 KV cache 分配。",Approach="从所附片段开始，打开固定提交阅读全文；图中学习顺序不是运行时调用关系。",Status="源码学习示例",Version="c6573eed5e56fd39b01d610db04616ed9b221851",Code="    def schedule(self, throttle_prefills: bool = False) -> SchedulerOutput:\n        self.current_step += 1\n        # NOTE(woosuk) on the scheduling algorithm:\n        # There's no \"decoding phase\" nor \"prefill phase\" in the scheduler.\n        # Each request just has the num_computed_tokens and\n        # num_tokens_with_spec. num_tokens_with_spec =\n        # len(prompt_token_ids) + len(output_token_ids) + len(spec_token_ids).\n        # At each step, the scheduler tries to assign tokens to the requests\n        # so that each request's num_computed_tokens can catch up its\n        # num_tokens_with_spec. This is general enough to cover\n        # chunked prefills, prefix caching, speculative decoding,\n        # and the \"jump decoding\" optimization in the future.\n\n        scheduled_new_reqs: list[Request] = []\n        scheduled_running_reqs: list[Request] = []\n        preempted_reqs: list[Request] = []\n\n        iteration_details = None",Sources="https://github.com/vllm-project/vllm/blob/c6573eed5e56fd39b01d610db04616ed9b221851/vllm/v1/core/sched/scheduler.py#L685",Learning=new NodeLearning{CodeUrl="https://github.com/vllm-project/vllm/blob/c6573eed5e56fd39b01d610db04616ed9b221851/vllm/v1/core/sched/scheduler.py#L685",Goal="观察 token 预算如何分配；沿本函数查找 KV cache 分配。",Question="一次调度返回什么？未完成的请求下轮如何继续？"}});
graph.Nodes.Add(new DomainNode{Id="kv",Title="管理 KV cache",Tier="CORE",Summary="理解逻辑 token 与缓存块管理之间的边界。",Approach="从所附片段开始，打开固定提交阅读全文；图中学习顺序不是运行时调用关系。",Status="源码学习示例",Version="c6573eed5e56fd39b01d610db04616ed9b221851",Code="class KVCacheManager:\n    def __init__(\n        self,\n        kv_cache_config: KVCacheConfig,\n        max_model_len: int,\n        scheduler_block_size: int,\n        hash_block_size: int,\n        max_in_flight_tokens: int | None = None,\n        enable_caching: bool = True,\n        use_eagle: bool = False,\n        num_hash_lookahead_tokens: int = 0,\n        num_prefill_lookahead: int = 0,\n        log_stats: bool = False,\n        enable_kv_cache_events: bool = False,\n        dcp_world_size: int = 1,\n        pcp_world_size: int = 1,\n        metrics_collector: KVCacheMetricsCollector | None = None,\n        watermark: float = 0.0,",Sources="https://github.com/vllm-project/vllm/blob/c6573eed5e56fd39b01d610db04616ed9b221851/vllm/v1/core/kv_cache_manager.py#L131",Learning=new NodeLearning{CodeUrl="https://github.com/vllm-project/vllm/blob/c6573eed5e56fd39b01d610db04616ed9b221851/vllm/v1/core/kv_cache_manager.py#L131",Goal="理解逻辑 token 与缓存块管理之间的边界。",Question="缓存块不足时，调度层需要做什么？"}});
graph.Nodes.Add(new DomainNode{Id="platform",Title="接入 Ascend 平台",Tier="CORE",Summary="从平台接口定位设备适配入口。",Approach="从所附片段开始，打开固定提交阅读全文；图中学习顺序不是运行时调用关系。",Status="源码学习示例",Version="fa4ce1bcd3ecc449265f380e117b3b17ebdac00c",Code="class NPUPlatform(Platform):\n    _enum = PlatformEnum.OOT\n    device_name: str = \"npu\"\n    device_type: str = \"npu\"\n    simple_compile_backend: str = \"eager\"  # Disable torch.compile()\n    ray_device_key: str = \"NPU\"\n    device_control_env_var: str = \"ASCEND_RT_VISIBLE_DEVICES\"\n    ray_noset_device_env_vars: list[str] = [\n        \"RAY_EXPERIMENTAL_NOSET_ASCEND_RT_VISIBLE_DEVICES\",\n    ]\n    dispatch_key: str = \"PrivateUse1\"\n\n    supported_quantization: list[str] = [\n        ASCEND_QUANTIZATION_METHOD,\n        COMPRESSED_TENSORS_METHOD,\n        FP8_METHOD,\n        \"deepseek_v4_fp8\",\n        \"modelopt_mxfp8\",",Sources="https://github.com/vllm-project/vllm-ascend/blob/fa4ce1bcd3ecc449265f380e117b3b17ebdac00c/vllm_ascend/platform.py#L101",Learning=new NodeLearning{CodeUrl="https://github.com/vllm-project/vllm-ascend/blob/fa4ce1bcd3ecc449265f380e117b3b17ebdac00c/vllm_ascend/platform.py#L101",Goal="从平台接口定位设备适配入口。",Question="哪些职责留在 vLLM，哪些由 NPU 平台提供？"}});
graph.Nodes.Add(new DomainNode{Id="attention",Title="选择 Ascend Attention 后端",Tier="CORE",Summary="追踪后端、metadata 与实现类的分工。",Approach="从所附片段开始，打开固定提交阅读全文；图中学习顺序不是运行时调用关系。",Status="源码学习示例",Version="fa4ce1bcd3ecc449265f380e117b3b17ebdac00c",Code="class AscendAttentionBackend(AttentionBackend):\n    accept_output_buffer: bool = True\n\n    @staticmethod\n    def get_name() -> str:\n        return \"CUSTOM\"\n\n    @classmethod\n    def supports_batch_invariance(cls) -> bool:\n        # vLLM #60271 added the batch-invariance support check in\n        # `init_attn_backend` in both supported vLLM revisions.\n        return True\n\n    @staticmethod\n    def get_impl_cls() -> type[\"AscendAttentionBackendImpl\"]:\n        if is_dcp_enabled():\n            from vllm_ascend.attention.context_parallel.attention_cp import AscendAttentionDCPImpl\n",Sources="https://github.com/vllm-project/vllm-ascend/blob/fa4ce1bcd3ecc449265f380e117b3b17ebdac00c/vllm_ascend/attention/attention_v1.py#L76",Learning=new NodeLearning{CodeUrl="https://github.com/vllm-project/vllm-ascend/blob/fa4ce1bcd3ecc449265f380e117b3b17ebdac00c/vllm_ascend/attention/attention_v1.py#L76",Goal="追踪后端、metadata 与实现类的分工。",Question="后端选择与 attention 数值计算有什么区别？"}});
